"""Synthetic command fixture; never calls a device or service."""
import hashlib
import json
import os
from pathlib import Path
import signal
import sys
import time
from urllib.parse import parse_qs, urlparse

tool = Path(sys.argv[0]).name
args = sys.argv[1:]
if tool == 'adb':
    assert args[:2] == ['-s', '002473611000997']
    args = args[2:]
with Path('calls.jsonl').open('a') as f:
    f.write(json.dumps([tool, *args]) + '\n')
scenario = os.environ.get('QA_SCENARIO', '')
skew = int(os.environ.get('QA_CLOCK_SKEW', '0'))

def installed():
    return json.loads(Path('installed.json').read_text())

def lines(nonce):
    now = time.time() + skew
    apk = installed()['sha256'] if scenario != 'probe-hash' else '0' * 64
    if scenario == 'missing-nonce':
        nonce = ''
    elif scenario == 'wrong-nonce':
        nonce = 'f' * 16
    code = f'TORSSH_PROBE PASS sdk={35 if tool == "adb" else 36} apk={apk}'
    if nonce:
        code += ' run=' + nonce
    stale = f'TORSSH_PROBE PASS sdk=35 apk={apk} run={"e" * 16}'
    if scenario == 'stale-only':
        code = stale
    result = [(now - .2, 'TorSSHChecks', stale)]
    if scenario == 'stale-fail':
        result.append((now, 'TorSSHChecks', 'TORSSH_PROBE FAIL run=' + 'e' * 16))
        # A right-nonce FAIL before the device bound is also stale.
        if tool == 'adb':
            result.append((now - 3600, 'TorSSHChecks', 'TORSSH_PROBE FAIL run=' + nonce))
    result.append((now, 'TorSSHChecks', code))
    if scenario == 'noise':
        result += [(now + .01, 'OtherApp', 'TORSSH_PROBE FAIL run=' + nonce)] * 5000
    return result

if (tool == 'rcsim' and args[0] == 'create') or args[0] == 'install':
    apk = Path(args[args.index('--install') + 1] if tool == 'rcsim' else args[-1])
    Path('installed.json').write_text(json.dumps(dict(
        path=str(apk), sha256=hashlib.sha256(apk.read_bytes()).hexdigest())))
    print(json.dumps(dict(id='test-session')))
elif tool == 'rcsim' and args[0] == 'release':
    Path('released').touch()
    print('released')
elif 'list' in args and 'packages' not in args:
    print('[]')
elif 'open-url' in args or ('am' in args and 'start' in args):
    url = next(a for a in args if a.startswith('torssh-debug:'))
    Path('nonce').write_text(parse_qs(urlparse(url).query)['run'][0])
    print('Starting: synthetic')
elif 'logs' in args or 'logcat' in args:
    if tool != 'adb' and '-f' in args:
        if scenario == 'follow-error':
            raise SystemExit(1)
        assert '--json' in args
        Path('reader-pid').write_text(str(os.getpid()))
        def stop(*_):
            Path('reader-stopped').touch()
            raise SystemExit(0)
        signal.signal(signal.SIGTERM, stop)
        while not Path('nonce').exists():
            time.sleep(.01)
        for epoch, tag, message in lines(Path('nonce').read_text()):
            print(json.dumps(dict(timestamp=epoch, tag=tag, message=message)), flush=True)
        while True:
            time.sleep(.05)
    elif tool == 'adb':
        rows = lines(Path('nonce').read_text())
        if '-s' in args:
            assert args[args.index('-s') + 1:] == ['TorSSHChecks:V', '*:S']
            rows = [r for r in rows if r[1] == 'TorSSHChecks']
        if '--uid' in args:
            assert args[args.index('--uid') + 1] == '10234'
        if '-T' in args:
            since = float(args[args.index('-T') + 1])
            rows = [r for r in rows if r[0] >= since]
        if '-t' in args:
            rows = rows[-int(args[args.index('-t') + 1]):]
        for epoch, tag, message in rows:
            print(f'{epoch:.9f} 10234 123 123 I {tag}: {message}')
    else:
        assert '--tail' in args
        for epoch, tag, message in lines(Path('nonce').read_text())[-1000:]:
            print(f'{epoch} {tag}: {message}')
elif 'pm' in args and 'path' in args:
    print('package:/data/app/~~safe/dev.torssh-token/base.apk')
    if scenario == 'split-apk':
        print('package:/data/app/~~safe/dev.torssh-token/split.apk')
elif 'sha256sum' in args:
    print(('0' * 64 if scenario == 'installed-hash' else installed()['sha256']) + '  ' + args[-1])
elif 'date' in args:
    value = time.time() + skew
    print(str(value) if args[-1] == '+%s.%N' and scenario != 'integer-date' else
          (str(int(value)) if args[-1] == '+%s' else str(int(value)) + '.%N'))
elif 'packages' in args:
    print('package:dev.torssh uid:10234')
elif 'pidof' in args:
    print('123')
elif 'screenshot' in args:
    Path(args[args.index('--output') + 1]).write_bytes(b'stub screenshot')
elif 'accessibility-tree' in args:
    print('{}')
elif 'getprop' in args:
    print('35')
elif 'getconf' in args:
    print('4096')
else:
    print('stub evidence')
